// Canonical email attribution. The two website assets are generated by
// scripts/sync-email-attribution.js; edit this source, then sync them.
const contents = {
  harmonculus: ["desktop_download", "mpc_download", "store", "privacy"],
  taype: ["desktop_download", "licences", "privacy"],
  "vintage-vocoder": ["desktop_download", "mpc_download", "privacy"],
  "mpc-loader": ["downloads", "setup_guide", "privacy"],
};

export function downloadEmailLink(value, product, content) {
  if (!Object.hasOwn(contents, product) || !contents[product].includes(content))
    throw new Error("invalid_email_attribution");
  const url = new URL(value);
  url.searchParams.set("utm_source", "download_email");
  url.searchParams.set("utm_medium", "email");
  url.searchParams.set("utm_campaign", product);
  url.searchParams.set("utm_content", content);
  return url.href;
}

// Retain the site's query-free page URL and pass only fixed, non-personal
// email campaign values to GA. Previously sent links have no utm_content.
export function downloadEmailCampaign(value) {
  const params = new URL(value).searchParams;
  for (const field of ["utm_source", "utm_medium", "utm_campaign"])
    if (params.getAll(field).length !== 1) return null;
  if (params.get("utm_source") !== "download_email" || params.get("utm_medium") !== "email") return null;
  const product = params.get("utm_campaign");
  const content = params.get("utm_content");
  if (!Object.hasOwn(contents, product) || params.getAll("utm_content").length > 1
      || (content !== null && !contents[product].includes(content))) return null;
  return {
    campaign_source: "download_email",
    campaign_medium: "email",
    campaign_name: product,
    ...(content === null ? {} : { campaign_content: content }),
  };
}
